def parse(tree):
    val, left, right = [tree[0]], [-1], [-1]
    i, u = 1, 0
    while u < len(val) and i < len(tree):
        for kids in (left, right):
            if i < len(tree):
                x = tree[i]
                i += 1
                if x != -1:
                    kids[u] = len(val)
                    val.append(x)
                    left.append(-1)
                    right.append(-1)
        u += 1
    return val, left, right


def inorder(tree):
    if not tree:
        return []
    val, left, right = parse(tree)
    out, stack, u = [], [], 0
    while stack or u != -1:
        while u != -1:
            stack.append(u)
            u = left[u]
        u = stack.pop()
        out.append(val[u])
        u = right[u]
    return out


def countPairsAcrossBsts(tree1, tree2, target):
    a, b = inorder(tree1), inorder(tree2)
    i, j = 0, len(b) - 1
    count = 0
    while i < len(a) and j >= 0:
        s = a[i] + b[j]
        if s == target:
            count += 1
            i += 1
            j -= 1
        elif s < target:
            i += 1
        else:
            j -= 1
    return count
